/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'fs'

// Parse command line arguments
function parseArgs(argv) {
  if (argv.length < 3) {
    throw new Error('usage: cli.js waves|explain|pack <workers>')
  }

  const command = argv[2]
  if (command === 'waves' || command === 'explain') {
    if (argv.length !== 3) {
      throw new Error('usage: cli.js waves|explain|pack <workers>')
    }
    return { command, workers: null }
  } else if (command === 'pack') {
    if (argv.length !== 4) {
      throw new Error('usage: cli.js waves|explain|pack <workers>')
    }
    const workers = argv[3]
    // Validate workers
    if (!/^\d+$/.test(workers) || workers === '0' || workers[0] === '0') {
      throw new Error('workers must be a positive integer')
    }
    return { command, workers: parseInt(workers, 10) }
  } else {
    throw new Error('usage: cli.js waves|explain|pack <workers>')
  }
}

// Valid task name pattern
const TASK_NAME_PATTERN = /^[A-Za-z0-9_.\-]+$/

// Parse input into tasks and dependencies
function parseInput(input) {
  const lines = input.split('\n')
  const tasks = new Map() // name -> cost
  const deps = new Map() // name -> Set of dependencies
  const taskLines = new Map() // name -> line number

  for (let i = 0; i < lines.length; i++) {
    let line = lines[i].trim()

    // Skip empty lines and comments
    if (!line || line.startsWith('#')) continue

    const lineNum = i + 1
    const words = line.split(/\s+/)

    if (words.length === 0) continue

    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new Error(`line ${lineNum}: expected task <name> <cost>`)
      }
      const name = words[1]
      const costStr = words[2]

      // Validate task name
      if (!TASK_NAME_PATTERN.test(name)) {
        throw new Error(`line ${lineNum}: invalid task name ${name}`)
      }

      // Validate cost
      if (!/^\d+$/.test(costStr)) {
        throw new Error(`line ${lineNum}: cost must be a non-negative integer`)
      }
      const cost = parseInt(costStr, 10)

      // Check for duplicate
      if (tasks.has(name)) {
        throw new Error(`line ${lineNum}: task ${name} is declared twice`)
      }

      tasks.set(name, cost)
      taskLines.set(name, lineNum)
      if (!deps.has(name)) {
        deps.set(name, new Set())
      }
    } else if (directive === 'dep') {
      if (words.length < 2) {
        throw new Error(`line ${lineNum}: expected dep <name> <dependency>...`)
      }
      const name = words[0]
      const dependencies = words.slice(2)

      if (!deps.has(name)) {
        deps.set(name, new Set())
      }

      for (const dep of dependencies) {
        deps.get(name).add(dep)
      }
    } else {
      throw new Error(`line ${lineNum}: unknown directive ${directive}`)
    }
  }

  // Verify all dependencies are declared
  for (const [name, depSet] of deps) {
    for (const dep of depSet) {
      if (!tasks.has(dep)) {
        throw new Error(`unknown task ${dep}`)
      }
    }
  }

  return { tasks, deps }
}

// Detect cycles using DFS
function detectCycle(tasks, deps) {
  const visited = new Set()
  const recStack = new Map() // name -> position in stack

  function dfs(node, stack) {
    visited.add(node)
    stack.push(node)
    recStack.set(node, stack.length - 1)

    const nodeDeps = deps.get(node) || new Set()
    // Sort dependencies for consistent cycle detection
    const sortedDeps = Array.from(nodeDeps).sort()

    for (const dep of sortedDeps) {
      if (!visited.has(dep)) {
        const cycle = dfs(dep, stack)
        if (cycle) return cycle
      } else if (recStack.has(dep)) {
        // Found a cycle
        const cycleStart = recStack.get(dep)
        const cycleTasks = stack.slice(cycleStart)
        return cycleTasks
      }
    }

    recStack.delete(node)
    stack.pop()
    return null
  }

  // Process all tasks in sorted order for consistent output
  const sortedTasks = Array.from(tasks.keys()).sort()
  for (const task of sortedTasks) {
    if (!visited.has(task)) {
      const cycle = dfs(task, [])
      if (cycle) {
        return cycle
      }
    }
  }

  return null
}

// Compute wave for each task
function computeWaves(tasks, deps) {
  const depth = new Map() // name -> wave depth
  const memo = new Map()

  function getDepth(name) {
    if (memo.has(name)) {
      return memo.get(name)
    }

    const nodeDeps = deps.get(name) || new Set()
    if (nodeDeps.size === 0) {
      memo.set(name, 0)
      return 0
    }

    let maxDepth = -1
    for (const dep of nodeDeps) {
      maxDepth = Math.max(maxDepth, getDepth(dep))
    }

    const taskDepth = maxDepth + 1
    memo.set(name, taskDepth)
    return taskDepth
  }

  for (const name of tasks.keys()) {
    depth.set(name, getDepth(name))
  }

  return depth
}

// Compute start and finish times for each task
function computeTiming(tasks, deps, waves) {
  const start = new Map() // name -> start time
  const finish = new Map() // name -> finish time
  const memo = new Map()

  function getStart(name) {
    if (memo.has(name)) {
      return memo.get(name).start
    }

    const nodeDeps = deps.get(name) || new Set()
    let maxFinish = 0

    for (const dep of nodeDeps) {
      const depFinish = getFinish(dep)
      maxFinish = Math.max(maxFinish, depFinish)
    }

    memo.set(name, { start: maxFinish, finish: null })
    return maxFinish
  }

  function getFinish(name) {
    if (memo.has(name) && memo.get(name).finish !== null) {
      return memo.get(name).finish
    }

    const startTime = getStart(name)
    const cost = tasks.get(name)
    const finishTime = startTime + cost

    if (!memo.has(name)) {
      memo.set(name, { start: startTime, finish: finishTime })
    } else {
      memo.get(name).finish = finishTime
    }

    return finishTime
  }

  for (const name of tasks.keys()) {
    const startTime = getStart(name)
    const finishTime = getFinish(name)
    start.set(name, startTime)
    finish.set(name, finishTime)
  }

  return { start, finish }
}

// Compute priority (longest chain starting at this task)
function computePriorities(tasks, deps) {
  const priorities = new Map()
  const memo = new Map()

  function getPriority(name) {
    if (memo.has(name)) {
      return memo.get(name)
    }

    const cost = tasks.get(name)
    const dependents = new Set()

    // Find all tasks that depend on this one
    for (const [taskName, taskDeps] of deps) {
      if (taskDeps.has(name)) {
        dependents.add(taskName)
      }
    }

    let maxChain = cost
    for (const dependent of dependents) {
      maxChain = Math.max(maxChain, cost + getPriority(dependent))
    }

    memo.set(name, maxChain)
    return maxChain
  }

  for (const name of tasks.keys()) {
    priorities.set(name, getPriority(name))
  }

  return priorities
}

// Simulate scheduling
function simulatePack(tasks, deps, numWorkers) {
  const start = new Map() // name -> actual start time
  const finish = new Map() // name -> actual finish time
  const workers = Array(numWorkers).fill(null).map(() => ({ free_at: 0, tasks: [] }))
  const priorities = computePriorities(tasks, deps)

  // Set to track completed tasks
  const completed = new Set()

  while (completed.size < tasks.size) {
    // Find all ready tasks
    const ready = []
    for (const [name, cost] of tasks) {
      if (completed.has(name)) continue

      const nodeDeps = deps.get(name) || new Set()
      let allDepsFinished = true
      let earliestDepFinish = 0

      for (const dep of nodeDeps) {
        if (!completed.has(dep)) {
          allDepsFinished = false
          break
        }
        earliestDepFinish = Math.max(earliestDepFinish, finish.get(dep))
      }

      if (allDepsFinished) {
        ready.push({ name, priority: priorities.get(name), earliestStart: earliestDepFinish })
      }
    }

    if (ready.length === 0) break

    // Sort by priority (descending) then by name (ascending)
    ready.sort((a, b) => {
      if (b.priority !== a.priority) return b.priority - a.priority
      return a.name.localeCompare(b.name)
    })

    // Assign to workers
    for (const task of ready) {
      // Find worker with earliest free time >= task's earliest start
      let bestWorker = -1
      let bestFreeTime = Infinity

      for (let i = 0; i < numWorkers; i++) {
        const freeTime = Math.max(workers[i].free_at, task.earliestStart)
        if (freeTime < bestFreeTime) {
          bestFreeTime = freeTime
          bestWorker = i
        }
      }

      const startTime = bestFreeTime
      const cost = tasks.get(task.name)
      const finishTime = startTime + cost

      start.set(task.name, startTime)
      finish.set(task.name, finishTime)
      completed.add(task.name)
      workers[bestWorker].tasks.push({ name: task.name, start: startTime, finish: finishTime })
      workers[bestWorker].free_at = finishTime
    }
  }

  return { workers, start, finish }
}

// Main function
function main() {
  try {
    // Parse arguments
    let args
    try {
      args = parseArgs(process.argv)
    } catch (e) {
      process.stderr.write(`error: ${e.message}\n`)
      process.exit(2)
    }

    // Read input
    const input = readFileSync(0, 'utf-8')

    // Parse input graph
    let tasks, deps
    try {
      const parsed = parseInput(input)
      tasks = parsed.tasks
      deps = parsed.deps
    } catch (e) {
      process.stderr.write(`error: ${e.message}\n`)
      process.exit(2)
    }

    // Detect cycles
    const cycle = detectCycle(tasks, deps)
    if (cycle) {
      const cycleStr = cycle.join(' -> ') + ' -> ' + cycle[0]
      process.stderr.write(`error: cycle: ${cycleStr}\n`)
      process.exit(3)
    }

    // Execute command
    if (args.command === 'waves') {
      const waves = computeWaves(tasks, deps)
      const { finish } = computeTiming(tasks, deps, waves)

      // Group tasks by wave
      const waveGroups = new Map()
      for (const [name, waveNum] of waves) {
        if (!waveGroups.has(waveNum)) {
          waveGroups.set(waveNum, [])
        }
        waveGroups.get(waveNum).push(name)
      }

      // Print waves
      const maxWave = waveGroups.size > 0 ? Math.max(...waveGroups.keys()) : -1
      for (let i = 0; i <= maxWave; i++) {
        const waveTaskNames = (waveGroups.get(i) || []).sort()
        process.stdout.write(`wave ${i}: ${waveTaskNames.join(' ')}\n`)
      }

      // Calculate total makespan
      let total = 0
      for (const finishTime of finish.values()) {
        total = Math.max(total, finishTime)
      }

      process.stdout.write(`total ${total}\n`)
    } else if (args.command === 'explain') {
      const waves = computeWaves(tasks, deps)
      const { start, finish } = computeTiming(tasks, deps, waves)

      // Sort tasks by name
      const taskNames = Array.from(tasks.keys()).sort()

      for (const name of taskNames) {
        const s = start.get(name)
        const f = finish.get(name)
        const d = waves.get(name)
        process.stdout.write(`${name} start=${s} finish=${f} depth=${d}\n`)
      }

      // Calculate total makespan
      let total = 0
      for (const finishTime of finish.values()) {
        total = Math.max(total, finishTime)
      }

      process.stdout.write(`total ${total}\n`)
    } else if (args.command === 'pack') {
      const { workers, start, finish } = simulatePack(tasks, deps, args.workers)

      // Print worker assignments
      for (let i = 0; i < workers.length; i++) {
        const taskList = workers[i].tasks
          .map(t => `${t.name}@${t.start}-${t.finish}`)
          .join(' ')
        if (taskList) {
          process.stdout.write(`worker ${i}: ${taskList}\n`)
        } else {
          process.stdout.write(`worker ${i}:\n`)
        }
      }

      // Calculate makespan
      let makespan = 0
      for (const w of workers) {
        if (w.free_at > makespan) {
          makespan = w.free_at
        }
      }

      process.stdout.write(`makespan ${makespan}\n`)
    }
  } catch (e) {
    console.error('Unexpected error:', e)
    process.exit(1)
  }
}

main()
